		waitForPass(() => assertEquals(2, consoleProvider.logTable.getRowCount()));
	}

	/* @Test */
	public void testProgress()
    {
		ProgressService progressService = addPlugin(tool, typeof(ProgressServicePlugin));
		using (CloseableTaskMonitor monitor1 = progressService.publishTask())
using (CloseableTaskMonitor monitor2 = progressService.publishTask())
{
			monitor1.initialize(10, "Testing 1");
			monitor2.initialize(10, "Testing 2");
			for (int i = 0; i < 10; i++) {
				Thread.sleep(100);
				monitor1.increment();
				Thread.sleep(100);
				monitor2.increment();
			}
		}
	}

	/* @Test */
	public void testRefTaskMonitor()
    {
		tool.execute(new _Anon_Task_1("Test"));
		Thread.sleep(100);
	}

	internal class _Anon_Task_1 : Task
	{
		public _Anon_Task_1() : @base("Test") {}

			/* @Override */
			public void run(TaskMonitor monitor)
    {
				monitor.initialize(10, "Testing");
				for (int i = 0; i < 10; i++) {
					try {
						Thread.sleep(100);
					}
					catch (InterruptedException e) {
						throw new AssertionError(e);
					}
